<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';import {botanicalAsset} from '../ui/botanical';import UiIcon from './UiIcon.vue'
type Media={scientificName:string;author:string;license:string;sourceUrl:string;imageUrl:string;width:number;height:number}
const props=withDefaults(defineProps<{name?:string|null;plantId?:number;eager?:boolean;caption?:boolean;sizes?:string}>(),{caption:true,sizes:'(max-width:700px) 100vw, 50vw'});const failedStatic=ref(false);const asset=computed(()=>failedStatic.value?undefined:botanicalAsset(props.name));const media=ref<Media|null>(null);let ctl:AbortController|undefined
async function load(){ctl?.abort();failedStatic.value=false;media.value=null;if(!props.plantId)return;ctl=new AbortController();const current=ctl;try{const r=await fetch(`/api/v1/plants/${props.plantId}/media`,{signal:ctl.signal});if(!r.ok)return;const rows=await r.json() as Media[];if(current!==ctl||current.signal.aborted)return;media.value=rows.find(x=>x.scientificName===props.name&&['CC0','CC-BY'].includes(x.license))??null}catch(e){if((e as Error).name!=='AbortError')media.value=null}}
onMounted(load);watch([()=>props.plantId,()=>props.name],load);onUnmounted(()=>ctl?.abort())
const srcset=computed(()=>{if(media.value){const base=media.value.imageUrl.replace(/-full\.webp$/, '');return `${base}-640.webp 640w, ${base}-960.webp 960w, ${media.value.imageUrl} ${media.value.width}w`}const image=asset.value;return image?[384,640,960].map(w=>`${image.file.replace('.webp','-'+w+'.webp')} ${w}w`).join(',')+`,${image.file} ${image.width}w`:undefined})
</script>
<template><figure class="botanical-image" :class="{'is-plate':!media&&asset?.kind==='plate','is-unillustrated':!media&&!asset}"><img v-if="media||asset" :src="media?.imageUrl||asset!.file" :srcset="srcset" :sizes="sizes" :alt="`${media?.scientificName||asset?.species} · 植物图鉴插图`" :loading="eager?'eager':'lazy'" :fetchpriority="eager?'high':'auto'" :width="media?.width||asset?.width" :height="media?.height||asset?.height" decoding="async" @error="media?media=null:failedStatic=true"/><div v-else class="botanical-unillustrated"><UiIcon name="leaf" :size="60"/><span>BOTANICAL RECORD</span><small>暂无对应授权图像</small></div><figcaption v-if="media||(caption&&asset)" :class="{'dynamic-media-credit':!!media}"><a v-if="media&&caption" :href="media.sourceUrl" target="_blank" rel="noopener noreferrer">{{media.author}} · {{media.license}}</a><span v-else-if="media" :title="`${media.author} · ${media.license}`">{{media.author}} · {{media.license}}</span><a v-else-if="asset" :href="asset.url" target="_blank" rel="noopener noreferrer">{{asset.credit}} · {{asset.license}}</a><span>图鉴插图，非鉴定证据</span></figcaption></figure></template>
